(x, y, t) => {
  // Warped coordinates with organic flow
  const cx = 240, cy = 120;
  const wx = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  const wy = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  const sx = x + wx, sy = y + wy;

  // Reaction-diffusion sources (energy nodes representing conservation)
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9]
  ];

  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }

  const act = aS/6, inh = iS/6;

  // Background field
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + 
             Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;

  // Spiral (gravity wells)
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;

  // Reaction
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);

  // Cell structure
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;

  const blend = reaction*0.75 + cell*0.25;
  const v = blend*0.5+0.5;

  // Neon palette
  const pal = [
    [5, 10, 30],      // deep navy
    [0, 180, 255],     // neon cyan
    [0, 255, 180],     // neon green (photosynthesis)
    [255, 220, 0],     // golden (energy/light)
    [255, 50, 100],    // neon magenta
    [180, 0, 255],     // neon purple
    [40, 15, 60],      // dark purple
    [5, 10, 30]        // deep navy (wrap)
  ];

  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;

  let r = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  let g = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  let b = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;

  // Now add UI elements...

  return [r|0, g|0, b|0];
}
